import time

from taf.selenium.gnb.oam.coam.cu.pages import v22R1, v21B, v22R2, v22R3, v22R4, v23R4, v25R1, v25R2, v25R3
from taf.selenium.gnb.oam.coam.cu.pages.LoginPage import CoamCULoginPage, LogoutPage
from taf.selenium.gnb.oam.coam.cu.pages.account_management import UserAccountManagement
from taf.selenium.gnb.oam.coam.cu.pages.alarms import Alarms
from taf.selenium.gnb.oam.coam.cu.pages.bts_status import BtsStatus
from taf.selenium.gnb.oam.coam.cu.pages.certificate_management import CertificateManagement
from taf.selenium.gnb.oam.coam.cu.pages.configuration import Configuration
from taf.selenium.gnb.oam.coam.cu.pages.dashboard import Dashboard
from taf.selenium.gnb.oam.coam.cu.pages.diagnostics import Diagnostic
from taf.selenium.gnb.oam.coam.cu.pages.performance import Performance


class Coam(object):
    def __init__(self, driver, version="default"):
        self._driver = driver
        self._login_page = CoamCULoginPage(self._driver, version)
        self._logout_page = LogoutPage(self._driver, version)
        self._configuration = Configuration(self._driver, version)
        self._alarm = Alarms(self._driver, version)
        self._userAccountManagement = UserAccountManagement(self._driver, version)
        self._diagnostic = Diagnostic(self._driver, version)
        self._dashboard = Dashboard(self._driver, version)
        self._btsStatus = BtsStatus(self._driver, version)
        self._certificateManagement = CertificateManagement(self._driver, version)
        self._performance = Performance(self._driver, version)

    @property
    def configuration(self):
        return self._configuration

    @property
    def alarms(self):
        return self._alarm

    @property
    def user_account_management(self):
        return self._userAccountManagement

    @property
    def diagnostic(self):
        return self._diagnostic

    @property
    def dashboard(self):
        return self._dashboard

    @property
    def certificate_management(self):
        return self._certificateManagement

    @property
    def bts_status(self):
        return self._btsStatus

    @property
    def performance(self):
        return self._performance

    def login(self, url, username, password, read_only_user, timeout):
        self._driver.set_page_load_timeout(timeout)
        self._driver.get(url)
        login_banner = self._login_page.login(username, password, read_only_user, int(timeout))
        time.sleep(5)
        return login_banner

    def logout(self, timeout):
        self._logout_page.logout(int(timeout))

    def close_browser(self):
        self._driver.quit()


class Coam21B(Coam):
    def __init__(self, driver, version='21b'):
        super(Coam21B, self).__init__(driver, version=version)
        self._certificateManagement = v21B.CertificateManagement(driver, version=version)


